def range_compress(nums):
    if not nums:
        return []
    uniq = sorted(set(nums))
    n = len(uniq)
    if n == 1:
        return [uniq]
    result = []
    i = 0
    while i < n:
        start = uniq[i]
        j = i
        while j + 1 < n and uniq[j + 1] == uniq[j] + 1:
            j += 1
        end = uniq[j]
        if j > i:
            result.append([start, end])
        else:
            result.append(start)
        i = j + 1
    return result
